let webhookPayload = null;
let targetVideoId = null;
let singleShortIndex = null;
let isSingleShort = false;
let isFullVideoOnly = false;

try {
  const webhookNode = $("Webhook Trigger (ByteWire Push)").first();
  webhookPayload = webhookNode?.json?.body || webhookNode?.json;
  targetVideoId = webhookPayload?.videoId;
  singleShortIndex = webhookPayload?.shortIndex || webhookPayload?.factIndex;
  isSingleShort = webhookPayload?.action === "post_reel" || webhookPayload?.event === "upload_single_short" || !!singleShortIndex;
  isFullVideoOnly = webhookPayload?.action === "post_full_video" || webhookPayload?.event === "upload_full_video";

  if (webhookPayload?.event === "ping" || webhookPayload?.action === "test_connection") {
    return [{ json: { skip: true, status: "ok", message: "ByteWire n8n Webhook connection verified successfully!" } }];
  }
} catch (_) {}

if (!targetVideoId) {
  return [{ json: { skip: true, message: "No videoId provided in webhook payload. Execution skipped." } }];
}

let token = webhookPayload?.token || webhookPayload?.callbackToken;
try {
  if (!token) {
    const loginData = $("1. Login to ByteWire API").first().json;
    token = loginData.token;
  }
} catch (_) {}

const allItems = $input.all().map(item => item.json);
const videoList = allItems.length === 1 && Array.isArray(allItems[0]) ? allItems[0] : allItems;

let pendingUploads = [];
if (isSingleShort) {
  // DEDUPLICATION: Find targeted video & verify this specific short has NOT already been posted
  pendingUploads = videoList.filter(v => {
    if (!v || String(v._id) !== String(targetVideoId)) return false;
    if (v.disableAutoUpload) return false;
    const s = (v.shorts || []).find((sh, idx) => Number(sh.factIndex) === Number(singleShortIndex) || (idx + 1) === Number(singleShortIndex));
    return s && !s.disableAutoUpload && !s.isPosted && !s.youtubeShortId && !s.youtubeShortUrl;
  });
} else {
  // DEDUPLICATION: Find targeted video & verify it has NOT already been posted
  pendingUploads = videoList.filter(v => v && String(v._id) === String(targetVideoId) && !v.disableAutoUpload && !v.youtubeVideoId && !v.isPosted && !v.youtubeUrl);
}

if (pendingUploads.length === 0) {
  return [{ json: { skip: true, message: "Video or short is already published or upload is disabled. Skipped to prevent duplicate posting." } }];
}

const video = pendingUploads[0];
return [{
  json: {
    skip: false,
    isSingleShort: isSingleShort,
    isFullVideoOnly: isFullVideoOnly,
    singleShortIndex: singleShortIndex,
    webhookPayload: webhookPayload,
    videoId: video._id,
    token: token,
    title: video.title,
    subject: video.subject,
    status: video.status,
    youtubeMetadata: video.youtubeMetadata || {},
    shorts: (video.shorts || []).slice(0, 3),
    shortsCount: Math.min(3, (video.shorts || []).length),
    videoUrl: "https://ytvideo.harikothapalli.space/videos/" + video._id + ".mp4",
    thumbnailUrl: "https://ytvideo.harikothapalli.space/thumbnails/" + video._id + ".png"
  }
}];

const video = $input.first().json;
const findPending = $("3. Find Pending Upload").first().json;
const isSingleShort = findPending.isSingleShort;
const isFullVideoOnly = findPending.isFullVideoOnly;
const singleShortIndex = Number(findPending.singleShortIndex) || 1;
const webhookPayload = findPending.webhookPayload || {};
const token = findPending.token;

if (isSingleShort) {
  const shorts = (video.shorts || []).slice(0, 3);
  const short = shorts.find((s, idx) => Number(s.factIndex) === singleShortIndex || (idx + 1) === singleShortIndex) || shorts[0] || {};
  const ytMeta = short.youtubeMetadata || {};
  const factTitle = short.factTitle || short.title || ("News Short #" + singleShortIndex);
  let rawTitle = webhookPayload.title || ytMeta.title || (factTitle + " 🚨 #Shorts");
  if (!rawTitle.toLowerCase().includes("#shorts")) {
    rawTitle = rawTitle.substring(0, 88) + " #Shorts";
  }
  const finalTitle = rawTitle.substring(0, 100);

  const parentLink = video.youtubeUrl ? ("\n\n📺 Watch the Full Breakdown: " + video.youtubeUrl) : "";
  let shortDesc = webhookPayload.description || ytMeta.description || ((short.scriptText || factTitle) + parentLink + "\n\n🔔 Subscribe to ByteWire for daily breaking news!\n\n#shorts #youtubeshorts #news #trending #viral #breakingnews #bytewire");
  if (!shortDesc.includes("#shorts")) {
    shortDesc += "\n\n#shorts #youtubeshorts #news #trending #viral #bytewire";
  }
  const shortTags = webhookPayload.tags || ytMeta.tags || ["shorts", "youtubeshorts", "news", "trending", "viral", "breaking news", "bytewire"];
  const videoDownloadUrl = "https://ytvideo.harikothapalli.space/api/download/" + video._id + "/short/" + singleShortIndex;
  const thumbnailDownloadUrl = webhookPayload.thumbnailDownloadUrl || ("https://ytvideo.harikothapalli.space/api/download/" + video._id + "/short/" + singleShortIndex + "/thumbnail");

  return [{
    json: {
      isSingleShort: true,
      isFullVideoOnly: false,
      videoId: video._id,
      shortIndex: singleShortIndex,
      token: token,
      title: finalTitle,
      description: shortDesc.substring(0, 5000),
      tags: shortTags.slice(0, 20).map(t => String(t).trim()).filter(Boolean),
      categoryId: "25",
      privacyStatus: "public",
      madeForKids: false,
      videoDownloadUrl: videoDownloadUrl,
      thumbnailUrl: thumbnailDownloadUrl,
      thumbnailDownloadUrl: thumbnailDownloadUrl,
      shorts: [],
      shortsCount: 0
    }
  }];
}

const meta = video.youtubeMetadata || {};
const title = (webhookPayload.title || meta.title || video.title || "Trending News Today").substring(0, 100);
let description = webhookPayload.description || meta.description || ("Top 10 " + video.subject + " news stories today. Watch for the latest verified updates and analysis.\n\n🔔 Subscribe to ByteWire for daily breaking reports.\n\n#news #breakingnews #trending #technews #bytewire");
if (!description.includes("#news")) {
  description += "\n\n#news #breakingnews #trending #viral #bytewire";
}
const tags = (webhookPayload.tags || meta.tags || ["news", "trending", "breaking news", "top 10", "bytewire"]).slice(0, 25).map(t => String(t).trim()).filter(Boolean);
const videoDownloadUrl = "https://ytvideo.harikothapalli.space/api/download/" + video._id;
const thumbnailDownloadUrl = webhookPayload.thumbnailDownloadUrl || ("https://ytvideo.harikothapalli.space/api/download/" + video._id + "/thumbnail");

return [{
  json: {
    isSingleShort: false,
    isFullVideoOnly: true,
    videoId: video._id,
    title: title,
    description: description.substring(0, 5000),
    tags: tags,
    categoryId: "25",
    privacyStatus: "public",
    madeForKids: false,
    videoDownloadUrl: videoDownloadUrl,
    thumbnailUrl: thumbnailDownloadUrl,
    thumbnailDownloadUrl: thumbnailDownloadUrl,
    shorts: (video.shorts || []).slice(0, 3),
    shortsCount: Math.min(3, (video.shorts || []).length),
    token: token
  }
}];

const ytNode = $("8. Upload to YouTube").first()?.json || {};
const youtubeId = ytNode.id || ytNode.uploadId || ytNode.videoId || ytNode?.snippet?.resourceId?.videoId || $input.first()?.json?.id || $input.first()?.json?.uploadId || "";
const preparedData = $("6. Prepare Video/Short Data").first().json;
const thumbResult = $input.first()?.json || {};
const hasThumbError = !!thumbResult?.error;

if (preparedData.isSingleShort) {
  if (youtubeId && preparedData.videoId && preparedData.token) {
    try {
      await fetch("https://ytvideo.harikothapalli.space/api/video/" + preparedData.videoId + "/short/" + preparedData.shortIndex + "/youtube", {
        method: "PATCH",
        headers: { "Content-Type": "application/json", "Authorization": "Bearer " + preparedData.token },
        body: JSON.stringify({ youtubeShortId: youtubeId, youtubeShortUrl: "https://www.youtube.com/shorts/" + youtubeId })
      });
    } catch (_) {}
  }
  return [{
    json: {
      status: "success",
      type: "short",
      shortIndex: preparedData.shortIndex,
      youtubeShortId: youtubeId,
      youtubeShortUrl: "https://www.youtube.com/shorts/" + youtubeId,
      message: "Short #" + preparedData.shortIndex + " published successfully to YouTube!"
    }
  }];
}

// Full Video upload complete
if (youtubeId && preparedData.videoId && preparedData.token) {
  try {
    await fetch("https://ytvideo.harikothapalli.space/api/video/" + preparedData.videoId + "/youtube", {
      method: "PATCH",
      headers: { "Content-Type": "application/json", "Authorization": "Bearer " + preparedData.token },
      body: JSON.stringify({ youtubeVideoId: youtubeId })
    });
  } catch (_) {}
}

return [{
  json: {
    status: "success",
    type: "full_video",
    youtubeVideoId: youtubeId,
    youtubeUrl: "https://www.youtube.com/watch?v=" + youtubeId,
    thumbnailStatus: hasThumbError ? "skipped_or_default" : "custom_thumbnail_set",
    message: "Full video uploaded successfully to YouTube! Link: https://www.youtube.com/watch?v=" + youtubeId
  }
}];

const result = $input.first().json;
return [{
  json: {
    status: "success",
    timestamp: new Date().toISOString(),
    ...result
  }
}];
